from __future__ import annotations
from qfap_adds.qfap_adds.project_management.report_link_titles import finalize_report_result
from frappe.utils.safe_exec import safe_exec
REPORT_SCRIPT='# Project Budget Performance v2.3 - Dynamic Controlled Assets\r\n# Frappe / ERPNext 16 Custom Script Report - Safe Execution\r\n# Actual expenditure is read live from submitted, non-cancelled GL Entries linked to Budget Line.\r\n\r\nfilters = filters or {}\r\nview_mode = filters.get("view_mode") or "Executive Budget"\r\nfrom_date = filters.get("from_date") or "1900-01-01"\r\nto_date = filters.get("to_date") or frappe.utils.nowdate()\r\nunder_utilized_threshold = float(filters.get("under_utilized_threshold") or 70)\r\nover_budget_only = int(filters.get("over_budget_only") or 0)\r\nattention_only = int(filters.get("attention_only") or 0)\r\ninclude_asset_expenses = int(filters.get("include_asset_expenses") or 0)\r\nselected_asset_accounts = filters.get("asset_accounts") or []\r\nif selected_asset_accounts and isinstance(selected_asset_accounts, str):\r\n    selected_asset_accounts = [selected_asset_accounts]\r\nclean_selected_asset_accounts = []\r\nseen_selected_asset_accounts = set()\r\nfor selected_asset_account in selected_asset_accounts:\r\n    if selected_asset_account and selected_asset_account not in seen_selected_asset_accounts:\r\n        seen_selected_asset_accounts.add(selected_asset_account)\r\n        clean_selected_asset_accounts.append(selected_asset_account)\r\nselected_asset_accounts = clean_selected_asset_accounts\r\nif include_asset_expenses == 1 and not selected_asset_accounts:\r\n    frappe.throw(_("Select at least one Asset Account Group / Account when Include Selected Asset Accounts is enabled."))\r\nif from_date > to_date:\r\n    frappe.throw(_("From Date cannot be later than To Date."))\r\n\r\nbase_columns = [\r\n    {"label": _("Project"), "fieldname": "project", "fieldtype": "Link", "options": "Project", "width": 125},\r\n    {"label": _("Project Name"), "fieldname": "project_name", "fieldtype": "Data", "width": 210},\r\n    {"label": _("Stage"), "fieldname": "project_stage", "fieldtype": "Data", "width": 130},\r\n    {"label": _("Project Manager"), "fieldname": "project_manager_name", "fieldtype": "Data", "width": 145},\r\n    {"label": _("Donor(s)"), "fieldname": "donor_display", "fieldtype": "Data", "width": 175},\r\n    {"label": _("Sector(s)"), "fieldname": "sector_display", "fieldtype": "Data", "width": 155},\r\n    {"label": _("Partner(s)"), "fieldname": "partner_display", "fieldtype": "Data", "width": 175},\r\n    {"label": _("Currency"), "fieldname": "currency", "fieldtype": "Link", "options": "Currency", "width": 85},\r\n    {"label": _("Approved Funding"), "fieldname": "approved_funding", "fieldtype": "Currency", "options": "currency", "width": 135},\r\n    {"label": _("Original Budget"), "fieldname": "original_budget", "fieldtype": "Currency", "options": "currency", "width": 125},\r\n    {"label": _("Approved Changes"), "fieldname": "approved_changes", "fieldtype": "Currency", "options": "currency", "width": 125},\r\n    {"label": _("Current Budget"), "fieldname": "current_budget", "fieldtype": "Currency", "options": "currency", "width": 125},\r\n    {"label": _("Actual Expense"), "fieldname": "actual_expense", "fieldtype": "Currency", "options": "currency", "width": 125},\r\n    {"label": _("Expense Accounts Actual"), "fieldname": "expense_account_actual", "fieldtype": "Currency", "options": "currency", "width": 155},\r\n    {"label": _("Selected Asset Actual"), "fieldname": "asset_account_actual", "fieldtype": "Currency", "options": "currency", "width": 145},\r\n    {"label": _("Available Balance"), "fieldname": "available_balance", "fieldtype": "Currency", "options": "currency", "width": 130},\r\n    {"label": _("Utilization"), "fieldname": "utilization_percentage", "fieldtype": "Percent", "width": 100},\r\n    {"label": _("Financial Status"), "fieldname": "financial_status", "fieldtype": "Data", "width": 135},\r\n    {"label": _("Funding Variance"), "fieldname": "funding_variance", "fieldtype": "Currency", "options": "currency", "width": 125},\r\n    {"label": _("Funding Coverage"), "fieldname": "funding_coverage", "fieldtype": "Percent", "width": 110},\r\n    {"label": _("Sector Allocation"), "fieldname": "sector_allocation", "fieldtype": "Currency", "options": "currency", "width": 135},\r\n    {"label": _("Sector Allocation %"), "fieldname": "sector_allocation_percentage", "fieldtype": "Percent", "width": 125},\r\n    {"label": _("Partner Allocation"), "fieldname": "partner_allocation", "fieldtype": "Currency", "options": "currency", "width": 135},\r\n    {"label": _("Partner Allocation %"), "fieldname": "partner_allocation_percentage", "fieldtype": "Percent", "width": 125},\r\n    {"label": _("Direct Implementation"), "fieldname": "direct_implementation", "fieldtype": "Currency", "options": "currency", "width": 145},\r\n    {"label": _("Unallocated Budget"), "fieldname": "unallocated_budget", "fieldtype": "Currency", "options": "currency", "width": 135},\r\n    {"label": _("Sector Allocation Status"), "fieldname": "sector_allocation_status", "fieldtype": "Data", "width": 150},\r\n    {"label": _("Partner Allocation Status"), "fieldname": "partner_allocation_status", "fieldtype": "Data", "width": 155},\r\n    {"label": _("Open Budget Changes"), "fieldname": "open_budget_changes", "fieldtype": "Int", "width": 130},\r\n    {"label": _("Budget Attention"), "fieldname": "budget_attention", "fieldtype": "Data", "width": 245},\r\n    {"label": _("Budget Line"), "fieldname": "budget_line", "fieldtype": "Link", "options": "Budget Line", "width": 125},\r\n    {"label": _("Budget Item"), "fieldname": "budget_item", "fieldtype": "Data", "width": 220},\r\n    {"label": _("Parent Budget Line"), "fieldname": "parent_budget_line", "fieldtype": "Link", "options": "Budget Line", "width": 140},\r\n    {"label": _("Group"), "fieldname": "is_group", "fieldtype": "Check", "width": 70},\r\n    {"label": _("Budget Line Status"), "fieldname": "budget_line_status", "fieldtype": "Data", "width": 120},\r\n    {"label": _("Budget Line Amount"), "fieldname": "budget_line_amount", "fieldtype": "Currency", "options": "currency", "width": 135},\r\n    {"label": _("Line Actual"), "fieldname": "line_actual", "fieldtype": "Currency", "options": "currency", "width": 120},\r\n    {"label": _("Line Balance"), "fieldname": "line_balance", "fieldtype": "Currency", "options": "currency", "width": 120},\r\n    {"label": _("Line Utilization"), "fieldname": "line_utilization", "fieldtype": "Percent", "width": 105},\r\n    {"label": _("Budget Share"), "fieldname": "budget_share", "fieldtype": "Percent", "width": 100}\r\n]\r\n\r\nif view_mode == "Budget Tree":\r\n    column_names = ["project", "project_name", "currency", "budget_line", "budget_item", "parent_budget_line", "is_group", "budget_line_status", "budget_line_amount", "line_actual", "line_balance", "line_utilization", "budget_share"]\r\nelif view_mode == "Donor Budget":\r\n    column_names = ["project", "project_name", "project_stage", "donor_display", "currency", "approved_funding", "current_budget", "actual_expense", "expense_account_actual", "asset_account_actual", "available_balance", "utilization_percentage", "financial_status", "funding_variance", "funding_coverage", "open_budget_changes", "budget_attention"]\r\nelif view_mode == "Sector Allocation":\r\n    column_names = ["project", "project_name", "sector_display", "currency", "current_budget", "sector_allocation", "sector_allocation_percentage", "unallocated_budget", "sector_allocation_status", "budget_attention"]\r\nelif view_mode == "Partner Allocation":\r\n    column_names = ["project", "project_name", "partner_display", "currency", "current_budget", "partner_allocation", "partner_allocation_percentage", "direct_implementation", "partner_allocation_status", "budget_attention"]\r\nelif view_mode == "Change Analysis":\r\n    column_names = ["project", "project_name", "currency", "original_budget", "approved_changes", "current_budget", "actual_expense", "expense_account_actual", "asset_account_actual", "available_balance", "utilization_percentage", "open_budget_changes", "budget_attention"]\r\nelif view_mode == "Full":\r\n    column_names = [x.get("fieldname") for x in base_columns]\r\nelse:\r\n    column_names = ["project", "project_name", "project_stage", "project_manager_name", "donor_display", "sector_display", "currency", "approved_funding", "current_budget", "actual_expense", "expense_account_actual", "asset_account_actual", "available_balance", "utilization_percentage", "financial_status", "funding_variance", "funding_coverage", "sector_allocation_percentage", "partner_allocation_percentage", "unallocated_budget", "open_budget_changes", "budget_attention"]\r\ncolumns = []\r\nfor base_column in base_columns:\r\n    if base_column.get("fieldname") in column_names:\r\n        columns.append(base_column)\r\n\r\nproject_meta = frappe.get_meta("Project")\r\nproject_fields = ["name", "project_name", "status", "company"]\r\nfor fieldname in ["custom_project_stage", "custom_project_manager", "custom_project_currency", "custom_approved_funding_amount", "custom_current_implementation_budget", "custom_total_sector_budget", "custom_unallocated_sector_budget", "custom_sector_budget_allocation_status", "custom_total_partner_allocation", "custom_partner_allocation_percentage", "custom_direct_implementation_amount", "custom_budget_allocation_status"]:\r\n    if project_meta.has_field(fieldname):\r\n        project_fields.append(fieldname)\r\nproject_filters = {}\r\nproject_values = filters.get("project") or []\r\nif project_values:\r\n    project_filters["name"] = ["in", project_values]\r\nstage_values = filters.get("project_stage") or []\r\nif stage_values and project_meta.has_field("custom_project_stage"):\r\n    project_filters["custom_project_stage"] = ["in", stage_values]\r\nmanager_values = filters.get("project_manager") or []\r\nif manager_values and project_meta.has_field("custom_project_manager"):\r\n    project_filters["custom_project_manager"] = ["in", manager_values]\r\ncompany_values = filters.get("company") or []\r\nif company_values:\r\n    project_filters["company"] = ["in", company_values]\r\ncurrency_values = filters.get("currency") or []\r\nif currency_values and project_meta.has_field("custom_project_currency"):\r\n    project_filters["custom_project_currency"] = ["in", currency_values]\r\nprojects = frappe.get_all("Project", filters=project_filters, fields=project_fields, order_by="project_name asc", limit_page_length=0)\r\n\r\nbudget_meta = frappe.get_meta("Budget Line") if frappe.db.exists("DocType", "Budget Line") else None\r\n\r\n# Expand selected Asset groups to enabled leaf Asset accounts for the selected companies.\r\nasset_leaf_accounts_by_company = {}\r\nif include_asset_expenses == 1 and selected_asset_accounts:\r\n    selected_asset_rows = frappe.db.sql("""\r\n        SELECT name, company, lft, rgt\r\n        FROM `tabAccount`\r\n        WHERE name IN %(selected_accounts)s\r\n          AND root_type = \'Asset\'\r\n          AND disabled = 0\r\n    """, {"selected_accounts": tuple(selected_asset_accounts)}, as_dict=1)\r\n    for selected_asset_row in selected_asset_rows:\r\n        company_name = selected_asset_row.get("company")\r\n        if company_name not in asset_leaf_accounts_by_company:\r\n            asset_leaf_accounts_by_company[company_name] = []\r\n        asset_descendants = frappe.db.sql("""\r\n            SELECT name\r\n            FROM `tabAccount`\r\n            WHERE company = %(company)s\r\n              AND root_type = \'Asset\'\r\n              AND disabled = 0\r\n              AND is_group = 0\r\n              AND lft >= %(lft)s\r\n              AND rgt <= %(rgt)s\r\n            ORDER BY lft\r\n        """, {"company": company_name, "lft": selected_asset_row.get("lft"), "rgt": selected_asset_row.get("rgt")}, as_dict=1)\r\n        for asset_descendant in asset_descendants:\r\n            account_name = asset_descendant.get("name")\r\n            if account_name and account_name not in asset_leaf_accounts_by_company[company_name]:\r\n                asset_leaf_accounts_by_company[company_name].append(account_name)\r\nif include_asset_expenses == 1 and selected_asset_accounts:\r\n    resolved_asset_account_count = 0\r\n    for company_name in asset_leaf_accounts_by_company:\r\n        resolved_asset_account_count = resolved_asset_account_count + len(asset_leaf_accounts_by_company.get(company_name) or [])\r\n    if resolved_asset_account_count == 0:\r\n        frappe.throw(_("The selected Asset accounts do not contain any enabled non-group Asset ledger accounts."))\r\n\r\nrows = []\r\nfor project in projects:\r\n    project_name = project.get("name")\r\n    manager = project.get("custom_project_manager") or ""\r\n    manager_name = frappe.db.get_value("Employee", manager, "employee_name") if manager else ""\r\n    currency = project.get("custom_project_currency") or ""\r\n\r\n    funding_rows = frappe.get_all("Project Funding Source", filters={"parent": project_name, "parenttype": "Project"}, fields=["donor", "is_primary_donor", "funding_status", "approved_amount_project_currency"], order_by="idx asc", limit_page_length=0)\r\n    donors = []\r\n    primary_donor = ""\r\n    approved_from_rows = 0.0\r\n    for funding_row in funding_rows:\r\n        donor = funding_row.get("donor") or ""\r\n        if donor and donor not in donors:\r\n            donors.append(donor)\r\n        if int(funding_row.get("is_primary_donor") or 0) == 1:\r\n            primary_donor = donor\r\n        if funding_row.get("funding_status") in ["Approved", "Partially Approved"]:\r\n            approved_from_rows += float(funding_row.get("approved_amount_project_currency") or 0)\r\n    if not primary_donor and donors:\r\n        primary_donor = donors[0]\r\n    donor_filter = filters.get("donor") or []\r\n    if donor_filter:\r\n        matched = False\r\n        for value in donor_filter:\r\n            if value in donors:\r\n                matched = True\r\n        if not matched:\r\n            continue\r\n\r\n    sector_rows = frappe.get_all("Project Sector", filters={"parent": project_name, "parenttype": "Project"}, fields=["sector", "is_primary_sector", "sector_budget"], order_by="idx asc", limit_page_length=0)\r\n    sectors = []\r\n    primary_sector = ""\r\n    sector_allocation = 0.0\r\n    for sector_row in sector_rows:\r\n        sector = sector_row.get("sector") or ""\r\n        if sector and sector not in sectors:\r\n            sectors.append(sector)\r\n        if int(sector_row.get("is_primary_sector") or 0) == 1:\r\n            primary_sector = sector\r\n        sector_allocation += float(sector_row.get("sector_budget") or 0)\r\n    if not primary_sector and sectors:\r\n        primary_sector = sectors[0]\r\n    sector_filter = filters.get("sector") or []\r\n    if sector_filter:\r\n        matched = False\r\n        for value in sector_filter:\r\n            if value in sectors:\r\n                matched = True\r\n        if not matched:\r\n            continue\r\n\r\n    partner_rows = frappe.get_all("Project Partner", filters={"parent": project_name, "parenttype": "Project"}, fields=["partner", "is_lead_partner", "allocated_amount_project_currency"], order_by="idx asc", limit_page_length=0)\r\n    partners = []\r\n    lead_partner = ""\r\n    partner_allocation = 0.0\r\n    for partner_row in partner_rows:\r\n        partner = partner_row.get("partner") or ""\r\n        if partner and partner not in partners:\r\n            partners.append(partner)\r\n        if int(partner_row.get("is_lead_partner") or 0) == 1:\r\n            lead_partner = partner\r\n        partner_allocation += float(partner_row.get("allocated_amount_project_currency") or 0)\r\n    if not lead_partner and partners:\r\n        lead_partner = partners[0]\r\n    partner_filter = filters.get("implementing_partner") or []\r\n    if partner_filter:\r\n        matched = False\r\n        for value in partner_filter:\r\n            if value in partners:\r\n                matched = True\r\n        if not matched:\r\n            continue\r\n\r\n    donor_display = primary_donor if (filters.get("donor_display_mode") or "Primary") == "Primary" else ", ".join(donors)\r\n    sector_display = primary_sector if (filters.get("sector_display_mode") or "Primary") == "Primary" else ", ".join(sectors)\r\n    partner_display = lead_partner if (filters.get("partner_display_mode") or "All") == "Primary" else ", ".join(partners)\r\n\r\n    approved_funding = float(project.get("custom_approved_funding_amount") or approved_from_rows or 0)\r\n    current_budget = float(project.get("custom_current_implementation_budget") or 0)\r\n    original_budget = 0.0\r\n    root_lines = []\r\n    all_lines = []\r\n    if budget_meta:\r\n        budget_fields = ["name"]\r\n        for fieldname in ["name1", "parent_budget_line", "line_cost", "currency", "is_group", "status", "project"]:\r\n            if budget_meta.has_field(fieldname):\r\n                budget_fields.append(fieldname)\r\n        all_lines = frappe.get_all("Budget Line", filters={"project": project_name}, fields=budget_fields, order_by="parent_budget_line asc, name asc", limit_page_length=0)\r\n        for budget_line in all_lines:\r\n            if not budget_line.get("parent_budget_line"):\r\n                root_lines.append(budget_line)\r\n        if len(root_lines) == 1:\r\n            original_budget = float(root_lines[0].get("line_cost") or 0)\r\n        elif root_lines:\r\n            for root_line in root_lines:\r\n                original_budget += float(root_line.get("line_cost") or 0)\r\n    if current_budget == 0:\r\n        current_budget = original_budget\r\n\r\n    # Live accounting actuals. All Expense accounts are included.\r\n    # Asset accounts are included only when enabled and explicitly selected.\r\n    actual_by_line = {}\r\n    project_expense_account_actual = 0.0\r\n    project_asset_account_actual = 0.0\r\n    project_actual_expense = 0.0\r\n    budget_line_names = []\r\n    for budget_line in all_lines:\r\n        if budget_line.get("name"):\r\n            budget_line_names.append(budget_line.get("name"))\r\n    if budget_line_names:\r\n        company_name = project.get("company")\r\n        selected_asset_leaf_accounts = asset_leaf_accounts_by_company.get(company_name) or []\r\n        gl_filters = {"company": company_name, "from_date": from_date, "to_date": to_date, "budget_lines": tuple(budget_line_names)}\r\n        actual_rows = []\r\n        if include_asset_expenses == 1 and selected_asset_leaf_accounts:\r\n            gl_filters["asset_accounts"] = tuple(selected_asset_leaf_accounts)\r\n            actual_rows = frappe.db.sql("""\r\n                SELECT gle.budget_line, acc.root_type, SUM(gle.debit - gle.credit) AS actual_amount\r\n                FROM `tabGL Entry` gle\r\n                INNER JOIN `tabAccount` acc ON acc.name = gle.account\r\n                WHERE gle.docstatus = 1\r\n                  AND gle.is_cancelled = 0\r\n                  AND gle.company = %(company)s\r\n                  AND acc.company = %(company)s\r\n                  AND gle.posting_date BETWEEN %(from_date)s AND %(to_date)s\r\n                  AND gle.budget_line IN %(budget_lines)s\r\n                  AND (acc.root_type = \'Expense\' OR gle.account IN %(asset_accounts)s)\r\n                GROUP BY gle.budget_line, acc.root_type\r\n            """, gl_filters, as_dict=1)\r\n        else:\r\n            actual_rows = frappe.db.sql("""\r\n                SELECT gle.budget_line, acc.root_type, SUM(gle.debit - gle.credit) AS actual_amount\r\n                FROM `tabGL Entry` gle\r\n                INNER JOIN `tabAccount` acc ON acc.name = gle.account\r\n                WHERE gle.docstatus = 1\r\n                  AND gle.is_cancelled = 0\r\n                  AND gle.company = %(company)s\r\n                  AND acc.company = %(company)s\r\n                  AND gle.posting_date BETWEEN %(from_date)s AND %(to_date)s\r\n                  AND gle.budget_line IN %(budget_lines)s\r\n                  AND acc.root_type = \'Expense\'\r\n                GROUP BY gle.budget_line, acc.root_type\r\n            """, gl_filters, as_dict=1)\r\n        for actual_row in actual_rows:\r\n            line_name = actual_row.get("budget_line")\r\n            actual_value = float(actual_row.get("actual_amount") or 0)\r\n            actual_by_line[line_name] = float(actual_by_line.get(line_name, 0) or 0) + actual_value\r\n            if actual_row.get("root_type") == "Asset":\r\n                project_asset_account_actual = project_asset_account_actual + actual_value\r\n            else:\r\n                project_expense_account_actual = project_expense_account_actual + actual_value\r\n            project_actual_expense = project_actual_expense + actual_value\r\n\r\n    available_balance = current_budget - project_actual_expense\r\n    utilization_percentage = project_actual_expense * 100 / current_budget if current_budget else 0\r\n    financial_status = "Not Assessed"\r\n    if current_budget == 0 and project_actual_expense > 0:\r\n        financial_status = "Unbudgeted Expense"\r\n    elif utilization_percentage > 100:\r\n        financial_status = "Over Budget"\r\n    elif utilization_percentage >= 100:\r\n        financial_status = "Fully Utilized"\r\n    elif utilization_percentage < under_utilized_threshold:\r\n        financial_status = "Under Utilized"\r\n    else:\r\n        financial_status = "Within Budget"\r\n\r\n    approved_changes = current_budget - original_budget if original_budget else 0.0\r\n    approved_change_sum = 0.0\r\n    open_budget_changes = 0\r\n    if frappe.db.exists("DocType", "Project Change Request"):\r\n        change_meta = frappe.get_meta("Project Change Request")\r\n        change_fields = ["name", "docstatus"]\r\n        for fieldname in ["status", "change_category", "budget_change_amount", "implementation_status"]:\r\n            if change_meta.has_field(fieldname):\r\n                change_fields.append(fieldname)\r\n        changes = frappe.get_all("Project Change Request", filters={"project": project_name}, fields=change_fields, limit_page_length=0)\r\n        for change in changes:\r\n            category = change.get("change_category") or ""\r\n            if category in ["Project Budget", "Budget Reallocation", "Budget Change"]:\r\n                if int(change.get("docstatus") or 0) == 1 or change.get("status") == "Approved":\r\n                    approved_change_sum += float(change.get("budget_change_amount") or 0)\r\n                if change.get("implementation_status") in ["Not Started", "In Progress", "Implementation Failed"]:\r\n                    open_budget_changes += 1\r\n    if approved_change_sum != 0:\r\n        approved_changes = approved_change_sum\r\n\r\n    sector_allocation_value = float(project.get("custom_total_sector_budget") or sector_allocation or 0)\r\n    partner_allocation_value = float(project.get("custom_total_partner_allocation") or partner_allocation or 0)\r\n    direct_implementation = float(project.get("custom_direct_implementation_amount") or 0)\r\n    if direct_implementation == 0 and current_budget > 0:\r\n        direct_implementation = max(current_budget - partner_allocation_value, 0)\r\n    unallocated_budget = float(project.get("custom_unallocated_sector_budget") or 0)\r\n    if unallocated_budget == 0 and current_budget > 0:\r\n        unallocated_budget = max(current_budget - sector_allocation_value, 0)\r\n    sector_percentage = sector_allocation_value * 100 / current_budget if current_budget else 0\r\n    partner_percentage = partner_allocation_value * 100 / current_budget if current_budget else 0\r\n    funding_variance = approved_funding - current_budget\r\n    funding_coverage = approved_funding * 100 / current_budget if current_budget else 0\r\n    sector_status = project.get("custom_sector_budget_allocation_status") or "Not Assessed"\r\n    partner_status = project.get("custom_budget_allocation_status") or "Not Assessed"\r\n\r\n    attention = []\r\n    if current_budget > approved_funding and approved_funding > 0:\r\n        attention.append(_("Budget exceeds approved funding"))\r\n    if sector_status in ["Over-Allocated", "Partially Allocated", "Not Allocated"]:\r\n        attention.append(_("Sector allocation: ") + sector_status)\r\n    if partner_status == "Over-Allocated":\r\n        attention.append(_("Partner allocation is over budget"))\r\n    if open_budget_changes:\r\n        attention.append(str(open_budget_changes) + " " + _("open budget changes"))\r\n    if current_budget == 0:\r\n        attention.append(_("Current budget not available"))\r\n    if include_asset_expenses == 1 and not selected_asset_accounts:\r\n        attention.append(_("Asset inclusion enabled without selected Asset accounts"))\r\n    if financial_status in ["Over Budget", "Unbudgeted Expense"]:\r\n        attention.append(_(financial_status))\r\n    elif financial_status == "Under Utilized":\r\n        attention.append(_("Under-utilized below ") + str(under_utilized_threshold) + "%")\r\n\r\n    summary_row = {\r\n        "project": project_name, "project_name": project.get("project_name"), "project_stage": project.get("custom_project_stage") or project.get("status"),\r\n        "project_manager": manager, "project_manager_name": manager_name, "all_donors": "|||".join(donors), "all_sectors": "|||".join(sectors), "all_partners": "|||".join(partners),\r\n        "primary_donor": primary_donor, "primary_sector": primary_sector, "lead_partner": lead_partner,\r\n        "donor_display": donor_display, "sector_display": sector_display, "partner_display": partner_display,\r\n        "currency": currency, "approved_funding": approved_funding, "original_budget": original_budget, "approved_changes": approved_changes,\r\n        "current_budget": current_budget, "actual_expense": project_actual_expense,\r\n        "expense_account_actual": project_expense_account_actual, "asset_account_actual": project_asset_account_actual,\r\n        "available_balance": available_balance,\r\n        "utilization_percentage": utilization_percentage, "financial_status": financial_status, "funding_variance": funding_variance, "funding_coverage": funding_coverage,\r\n        "sector_allocation": sector_allocation_value, "sector_allocation_percentage": sector_percentage,\r\n        "partner_allocation": partner_allocation_value, "partner_allocation_percentage": partner_percentage,\r\n        "direct_implementation": direct_implementation, "unallocated_budget": unallocated_budget,\r\n        "sector_allocation_status": sector_status, "partner_allocation_status": partner_status,\r\n        "open_budget_changes": open_budget_changes, "budget_attention": "; ".join(attention)\r\n    }\r\n\r\n    if attention_only == 1 and not summary_row.get("budget_attention"):\r\n        continue\r\n    if over_budget_only == 1 and financial_status not in ["Over Budget", "Unbudgeted Expense"]:\r\n        continue\r\n\r\n    if view_mode == "Budget Tree":\r\n        # Roll actuals upward from children to groups.\r\n        rolled_actual = {}\r\n        for budget_line in all_lines:\r\n            rolled_actual[budget_line.get("name")] = float(actual_by_line.get(budget_line.get("name"), 0) or 0)\r\n        for budget_line in all_lines[::-1]:\r\n            parent_name = budget_line.get("parent_budget_line")\r\n            if parent_name:\r\n                rolled_actual[parent_name] = float(rolled_actual.get(parent_name, 0) or 0) + float(rolled_actual.get(budget_line.get("name"), 0) or 0)\r\n        for budget_line in all_lines:\r\n            line_amount = float(budget_line.get("line_cost") or 0)\r\n            tree_row = {}\r\n            for key in summary_row:\r\n                tree_row[key] = summary_row[key]\r\n            tree_row["budget_line"] = budget_line.get("name")\r\n            tree_row["budget_item"] = budget_line.get("name1") or budget_line.get("name")\r\n            tree_row["parent_budget_line"] = budget_line.get("parent_budget_line")\r\n            tree_row["is_group"] = int(budget_line.get("is_group") or 0)\r\n            tree_row["budget_line_status"] = budget_line.get("status") or ""\r\n            tree_row["budget_line_amount"] = line_amount\r\n            tree_row["line_actual"] = float(rolled_actual.get(budget_line.get("name"), 0) or 0)\r\n            tree_row["line_balance"] = line_amount - tree_row.get("line_actual")\r\n            tree_row["line_utilization"] = tree_row.get("line_actual") * 100 / line_amount if line_amount else 0\r\n            tree_row["budget_share"] = line_amount * 100 / current_budget if current_budget else 0\r\n            rows.append(tree_row)\r\n    else:\r\n        rows.append(summary_row)\r\n\r\nattention_rows = []\r\nnormal_rows = []\r\nfor row in rows:\r\n    if row.get("budget_attention"):\r\n        attention_rows.append(row)\r\n    else:\r\n        normal_rows.append(row)\r\nrows = attention_rows + normal_rows\r\n\r\ntotal_projects = len(rows) if view_mode != "Budget Tree" else 0\r\nif view_mode == "Budget Tree":\r\n    distinct_projects = []\r\n    for row in rows:\r\n        if row.get("project") not in distinct_projects:\r\n            distinct_projects.append(row.get("project"))\r\n    total_projects = len(distinct_projects)\r\ntotal_current_budget = 0.0\r\ntotal_actual_expense = 0.0\r\ntotal_expense_account_actual = 0.0\r\ntotal_asset_account_actual = 0.0\r\ntotal_approved_funding = 0.0\r\ntotal_unallocated = 0.0\r\nattention_count = 0\r\ncurrencies = []\r\nseen_projects = []\r\nfor row in rows:\r\n    if row.get("project") in seen_projects:\r\n        continue\r\n    seen_projects.append(row.get("project"))\r\n    total_current_budget += float(row.get("current_budget") or 0)\r\n    total_actual_expense += float(row.get("actual_expense") or 0)\r\n    total_expense_account_actual += float(row.get("expense_account_actual") or 0)\r\n    total_asset_account_actual += float(row.get("asset_account_actual") or 0)\r\n    total_approved_funding += float(row.get("approved_funding") or 0)\r\n    total_unallocated += float(row.get("unallocated_budget") or 0)\r\n    if row.get("budget_attention"):\r\n        attention_count += 1\r\n    if row.get("currency") and row.get("currency") not in currencies:\r\n        currencies.append(row.get("currency"))\r\nreport_summary = [\r\n    {"value": total_projects, "indicator": "Blue", "label": _("Projects"), "datatype": "Int"},\r\n    {"value": attention_count, "indicator": "Red" if attention_count else "Green", "label": _("Need Attention"), "datatype": "Int"},\r\n    {"value": total_unallocated, "indicator": "Orange" if total_unallocated else "Green", "label": _("Unallocated Budget"), "datatype": "Currency", "currency": currencies[0] if len(currencies) == 1 else ""}\r\n]\r\nif len(currencies) == 1:\r\n    report_summary.append({"value": total_approved_funding, "indicator": "Blue", "label": _("Approved Funding") + " (" + currencies[0] + ")", "datatype": "Currency", "currency": currencies[0]})\r\n    report_summary.append({"value": total_current_budget, "indicator": "Blue", "label": _("Current Budget") + " (" + currencies[0] + ")", "datatype": "Currency", "currency": currencies[0]})\r\n    report_summary.append({"value": total_actual_expense, "indicator": "Blue", "label": _("Total Actual") + " (" + currencies[0] + ")", "datatype": "Currency", "currency": currencies[0]})\r\n    report_summary.append({"value": total_expense_account_actual, "indicator": "Blue", "label": _("Expense Accounts Actual") + " (" + currencies[0] + ")", "datatype": "Currency", "currency": currencies[0]})\r\n    if include_asset_expenses == 1 and selected_asset_accounts:\r\n        report_summary.append({"value": total_asset_account_actual, "indicator": "Blue", "label": _("Selected Asset Actual") + " (" + currencies[0] + ")", "datatype": "Currency", "currency": currencies[0]})\r\n    report_summary.append({"value": total_current_budget - total_actual_expense, "indicator": "Red" if total_actual_expense > total_current_budget else "Green", "label": _("Available Balance") + " (" + currencies[0] + ")", "datatype": "Currency", "currency": currencies[0]})\r\n\r\nchart_by = filters.get("chart_by") or "Allocation Status"\r\nchart_counts = {}\r\nfor row in rows:\r\n    if view_mode == "Budget Tree" and int(row.get("is_group") or 0) == 1:\r\n        continue\r\n    key = row.get("sector_allocation_status") or _("Not Assessed")\r\n    if chart_by == "Funding Coverage":\r\n        coverage = float(row.get("funding_coverage") or 0)\r\n        key = _("Fully Covered") if coverage >= 100 else (_("Partially Covered") if coverage > 0 else _("Not Funded"))\r\n    elif chart_by == "Project":\r\n        key = row.get("project_name") or row.get("project")\r\n    elif chart_by == "Donor":\r\n        key = row.get("primary_donor") or _("Not Specified")\r\n    elif chart_by == "Sector":\r\n        key = row.get("primary_sector") or _("Not Specified")\r\n    chart_counts[key] = chart_counts.get(key, 0) + 1\r\nchart_labels=[]\r\nchart_values=[]\r\nfor key in chart_counts:\r\n    chart_labels.append(key)\r\n    chart_values.append(chart_counts[key])\r\nchart={"data":{"labels":chart_labels,"datasets":[{"name":_("Projects"),"values":chart_values}]},"type":"donut" if chart_by in ["Allocation Status","Funding Coverage"] else "bar","height":320,"colors":["#1565C0","#2E7D32","#F9A825","#C62828","#6A1B9A","#00838F"]}\r\nmessage = ""\r\nif not rows:\r\n    message = _("No budget records match the selected filters.")\r\nelif len(currencies) > 1:\r\n    message = _("Multiple currencies are present. Portfolio monetary totals are intentionally excluded. Use the Currency filter for comparable totals.")\r\nelse:\r\n    if include_asset_expenses == 1 and selected_asset_accounts:\r\n        message = _("Actuals include all Expense accounts plus enabled leaf Asset accounts under the selected Asset groups/accounts. Expense and selected Asset actuals are shown separately and combined in Total Actual.")\r\n    else:\r\n        message = _("Actuals include all Expense accounts only. Enable and select Asset accounts when eligible project asset purchases must also be included.")\r\ndata=(columns,rows,message,chart,report_summary,1)\r\n'
def _apply_native_sticky(result):
    if not result:
        return result
    values = list(result) if isinstance(result, (tuple, list)) else [result]
    if not values:
        return result
    columns = values[0] or []
    for index, column in enumerate(columns):
        if isinstance(column, dict):
            column["sticky"] = bool(index < 2)
    values[0] = columns
    return tuple(values)

def execute(filters=None):
    local_vars={"filters":filters or {}}
    safe_exec(REPORT_SCRIPT,None,local_vars,script_filename='Project Budget')
    return finalize_report_result(local_vars.get("data") or ([], []))
